<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,base,token,download,materialText} from './api'
import ScoreChart from './ScoreChart.vue'
type Row=Record<string,any>
const user=ref<Row|null>(null),page=ref('overview'),busy=ref(false),error=ref('')
const loginForm=reactive({username:'',password:''})
const selectedDemo=ref('')
const demoAccounts=[
  {username:'teacher_a',label:'A 班教师 · teacher_a',password:import.meta.env.VITE_NEXUS_DEMO_TEACHER_PASSWORD},
  {username:'student_a1',label:'A 班学生 · student_a1',password:import.meta.env.VITE_NEXUS_DEMO_STUDENT_PASSWORD},
  {username:'student_a2',label:'A 班学生 · student_a2',password:import.meta.env.VITE_NEXUS_DEMO_STUDENT_PASSWORD},
  {username:'teacher_b',label:'B 班教师 · teacher_b',password:import.meta.env.VITE_NEXUS_DEMO_TEACHER_PASSWORD},
  {username:'student_b1',label:'B 班学生 · student_b1',password:import.meta.env.VITE_NEXUS_DEMO_STUDENT_PASSWORD},
].filter(account=>account.password)
function selectDemoAccount(username:string){
  const account=demoAccounts.find(item=>item.username===username)
  loginForm.username=account?.username||''
  loginForm.password=account?.password||''
}
const lists=reactive<Record<string,Row[]>>({agents:[],templates:[],skills:[],materials:[],gaps:[],assignments:[],papers:[],submissions:[],weekly:[],tasks:[],audit:[],conversations:[],students:[],wrong:[]})
const teacher=computed(()=>user.value?.role==='teacher')
const nav=computed(()=>[{id:'overview',label:'工作台'},{id:'chat',label:'学习助手'},{id:'materials',label:'讲义知识库'},...(teacher.value?[{id:'config',label:'应用与技能'},{id:'gaps',label:'知识缺口'}]:[]),{id:'assignments',label:'作业与批改'},{id:'weekly',label:'学情周报'},...(teacher.value?[{id:'tasks',label:'后台任务'},{id:'audit',label:'调用记录'}]:[])])
const title=computed(()=>nav.value.find(n=>n.id===page.value)?.label||'工作台')
const stateNames:Record<string,string>={pending:'待确认',approved:'审核通过',rejected:'已驳回',indexing:'索引中',filled:'已补入',index_failed:'索引失败',active:'生效',superseded:'历史版本',withdrawn:'已撤回',draft:'草稿',published:'已发布',issuing:'发卷中',ready:'可作答',frozen:'作答中',submitted:'已提交',issue_failed:'发卷失败',queued:'排队中',running:'执行中',succeeded:'已完成',failed:'失败',dispatch_failed:'等待重新入队',grading:'批改中',graded:'已批改',grade_failed:'批改失败',reviewed:'已复核',generating:'生成中',generation_failed:'生成失败'}
const state=(s:string)=>stateNames[s]||s
const date=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—'
async function action(fn:()=>Promise<any>){error.value='';busy.value=true;try{return await fn()}catch(e:any){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}
async function load(){
  const common=['agents','templates','skills','materials','assignments','papers','submissions','weekly','conversations']
  const extra=teacher.value?['gaps','tasks','audit','students']:[]
  const results=await Promise.all([...common,...extra].map(async name=>[name,await api('/'+name)] as const))
  for(const [name,value] of results)lists[name]=value
  lists.wrong=await api('/wrong-questions')
}
async function login(){await action(async()=>{const result=await api('/login','POST',loginForm);localStorage.setItem('nexus-token',result.token);user.value=result.user;await load();loginForm.password=''})}
async function logout(){await action(async()=>{await api('/logout','POST');localStorage.removeItem('nexus-token');user.value=null;chatRows.value=[];selectedDemo.value='';loginForm.username='';loginForm.password=''})}
let refreshTimer:ReturnType<typeof setInterval>
onMounted(async()=>{if(token())await action(async()=>{user.value=await api('/me');await load()});refreshTimer=setInterval(()=>{if(user.value&&!busy.value&&['tasks','materials','assignments','weekly','gaps'].includes(page.value))load().catch(()=>{})},7000)})
onBeforeUnmount(()=>clearInterval(refreshTimer))
const templateForm=reactive({id:0,name:'',content:''})
async function saveTemplate(){await action(async()=>{await api('/templates'+(templateForm.id?'/'+templateForm.id:''),templateForm.id?'PATCH':'POST',{name:templateForm.name,content:templateForm.content});Object.assign(templateForm,{id:0,name:'',content:''});await load();ElMessage.success('模板已保存')})}
const skillFile=ref<File>();const materialFile=ref<File>();const materialTitle=ref('');const replaceId=ref<number|null>(null)
const materialPreview=ref<{id:number,content:string}|null>(null)
async function previewMaterial(row:Row){
  if(materialPreview.value?.id===row.id){materialPreview.value=null;return}
  await action(async()=>{materialPreview.value={id:row.id,content:await materialText(row.id)}})
}
function fileChange(event:Event,kind:string){const file=(event.target as HTMLInputElement).files?.[0];if(kind==='skill')skillFile.value=file;else materialFile.value=file}
async function uploadSkill(){await action(async()=>{if(!skillFile.value)throw new Error('请选择技能文件');const form=new FormData();form.append('file',skillFile.value);await api('/skills','POST',form);await load();ElMessage.success('技能已上传')})}
async function uploadMaterial(){await action(async()=>{if(!materialFile.value)throw new Error('请选择讲义');const form=new FormData();form.append('file',materialFile.value);form.append('title',materialTitle.value);await api(replaceId.value?`/materials/${replaceId.value}/versions`:'/materials','POST',form);await load();ElMessage.success('已提交索引任务，完成后生效')})}
const agentForm=reactive<Row>({id:0,name:'',prompt:'根据本班讲义引导学习，资料不足时说明。',template_id:null,material_ids:[],skill_ids:[],tools:[],enabled:true})
const toolOptions=[['lecture_search','讲义检索'],['current_assignments','当前作业'],['my_wrong_questions','个人错题'],['assignment_rubric','作业评分规则'],['class_statistics','班级统计（教师）']]
function editAgent(row:Row){Object.assign(agentForm,JSON.parse(JSON.stringify(row)));document.getElementById('agent-form')?.scrollIntoView({behavior:'smooth'})}
async function saveAgent(){await action(async()=>{const {id,name,prompt,template_id,material_ids,skill_ids,tools,enabled}=agentForm;await api('/agents'+(id?'/'+id:''),id?'PATCH':'POST',{name,prompt,template_id,material_ids,skill_ids,tools,enabled});await load();ElMessage.success('应用已保存')})}
const conversationId=ref<number|null>(null),agentId=ref<number|null>(null),chatRows=ref<Row[]>([]),question=ref(''),sending=ref(false),toolEvents=ref<Row[]>([]),snapshot=ref<Row|null>(null)
async function openConversation(row:Row){await action(async()=>{conversationId.value=row.id;agentId.value=row.agent_id;chatRows.value=await api(`/conversations/${row.id}/messages`);toolEvents.value=[]})}
async function createConversation(){await action(async()=>{if(!agentId.value)throw new Error('请选择学习助手');const row=await api('/conversations','POST',{agent_id:agentId.value});conversationId.value=row.id;chatRows.value=[];toolEvents.value=[];await load()})}
async function ask(){
  if(!question.value.trim()||sending.value)return
  await action(async()=>{
    if(!conversationId.value){if(!agentId.value)throw new Error('请选择学习助手');const row=await api('/conversations','POST',{agent_id:agentId.value});conversationId.value=row.id}
    const text=question.value;question.value='';chatRows.value.push({role:'user',content:text});const answer=reactive<Row>({role:'assistant',content:'',citations:[]});chatRows.value.push(answer);sending.value=true
    try{
      const response=await fetch(base+`/conversations/${conversationId.value}/messages`,{method:'POST',credentials:'omit',headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'},body:JSON.stringify({question:text})})
      if(!response.ok)throw new Error((await response.json()).error||'请求失败')
      const reader=response.body!.getReader(),decoder=new TextDecoder();let buffer='',doneEvent=false
      while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value,{stream:!done});buffer=buffer.replace(/\r\n/g,'\n');let end
        while((end=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,end);buffer=buffer.slice(end+2);const line=frame.split('\n').filter(x=>x.startsWith('data:')).map(x=>x.slice(5)).join('\n');if(!line)continue;const item=JSON.parse(line)
          if(item.event==='meta'){answer.citations=item.citations;answer.skill=item.skill;answer.gap_id=item.gap_id}
          else if(item.event==='delta')answer.content+=item.text
          else if(item.event==='tool')toolEvents.value.push(item)
          else if(item.event==='done')doneEvent=true
          else if(item.event==='error')throw new Error(item.error)
        }if(done)break
      }
      if(!doneEvent)throw new Error('连接中断，本轮未确认保存，请重新打开会话检查')
      await load()
    }finally{sending.value=false}
  })
}
async function reviewGap(row:Row,decision:string){await action(async()=>{await api(`/gaps/${row.id}/review`,'POST',{decision,note:''});await load()})}
const supplementForm=reactive({id:0,title:'',content:''})
async function supplement(){await action(async()=>{await api(`/gaps/${supplementForm.id}/supplement`,'POST',supplementForm);supplementForm.id=0;await load();ElMessage.success('补充材料正在索引')})}
const assignmentForm=reactive({title:'参数运算练习',question_template:'计算 ({a}+{b})×2，写出计算过程与结果。',ranges:'{"a":[10,99],"b":[2,20]}',answer_expression:'(a+b)*2',rubric:'[{"name":"计算过程","points":40},{"name":"最终答案","points":60}]',deadline:new Date(Date.now()+86400000*3).toISOString().slice(0,16)})
async function newAssignment(){await action(async()=>{await api('/assignments','POST',{...assignmentForm,ranges:JSON.parse(assignmentForm.ranges),rubric:JSON.parse(assignmentForm.rubric),deadline:new Date(assignmentForm.deadline).toISOString()});await load();ElMessage.success('作业草稿已保存')})}
async function publishAssignment(id:number){await action(async()=>{await api(`/assignments/${id}/publish`,'POST');await load();ElMessage.success('发卷任务已加入队列')})}
const answerForm=reactive({id:0,question:'',answer:''})
async function startPaper(row:Row){await action(async()=>{const value=await api(`/papers/${row.id}/start`,'POST');Object.assign(answerForm,{id:row.id,question:value.question,answer:''});await load()})}
async function submitPaper(){await action(async()=>{await api(`/papers/${answerForm.id}/submit`,'POST',{answer:answerForm.answer});answerForm.id=0;await load();ElMessage.success('已提交，正在等待批改')})}
async function reviewScore(row:Row){await action(async()=>{const value=await ElMessageBox.prompt('填写最终分数（0–100）','教师复核',{inputValue:String(row.final_score??'')});const note=await ElMessageBox.prompt('填写改分或确认依据','复核说明');await api(`/submissions/${row.id}/review`,'POST',{score:Number(value.value),note:note.value});await load()})}
async function newWeekly(){await action(async()=>{await api('/weekly','POST');await load();ElMessage.success('已提交本周报告生成任务')})}
async function publishWeekly(row:Row){await action(async()=>{await api(`/weekly/${row.id}/publish`,'POST',{comment:row.teacher_comment});await load();ElMessage.success('周报已发布')})}
async function retryTask(row:Row){await action(async()=>{await api(`/tasks/${row.id}/retry`,'POST');await load()})}
async function withdraw(row:Row){await action(async()=>{await ElMessageBox.confirm('撤回后不再用于新的检索，已有问答引用会保留。','撤回讲义');await api(`/materials/${row.id}/withdraw`,'POST');await load()})}
const studentName=(id:number)=>lists.students.find(s=>s.id===id)?.username||`学生 ${id}`
const assignmentName=(id:number)=>lists.assignments.find(s=>s.id===id)?.title||`作业 ${id}`
</script>

<template>
  <div v-if="!user" class="login-page">
    <section class="login-intro"><div class="eyebrow">CAMPUSCLAW NEXUS</div><h1>让问题回到课堂，<br>让学习留下依据。</h1><p>讲义检索 · 学习助手 · 作业反馈<br>教师与学生共享一个持续完善的知识空间。</p></section>
    <section class="login-box"><form class="login-form" @submit.prevent="login"><h2>登录教学平台</h2><p class="muted">使用教师或学生账号进入自己的班级</p><div v-if="error" class="error">{{error}}</div><template v-if="demoAccounts.length"><label for="demo-account">选择演示账号</label><el-select id="demo-account" v-model="selectedDemo" placeholder="请选择教师或学生" @change="selectDemoAccount"><el-option v-for="account in demoAccounts" :key="account.username" :label="account.label" :value="account.username"/></el-select><p class="muted demo-hint">选择后自动填入用户名和密码，也可以在下方手动修改。</p></template><label for="username">用户名</label><el-input id="username" v-model="loginForm.username" autocomplete="username" placeholder="请输入用户名"/><label for="password">密码</label><el-input id="password" v-model="loginForm.password" type="password" show-password autocomplete="current-password"/><el-button type="primary" native-type="submit" :loading="busy">登录</el-button></form></section>
  </div>
  <div v-else class="shell">
    <aside class="sidebar"><div class="brand">CampusClaw<small>NEXUS · 教学空间</small></div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="page=item.id">{{item.label}}</button></nav><div class="account"><b>{{user.username}}</b><br>{{user.class_id}} 班 · {{teacher?'教师':'学生'}}<br><el-button text style="color:#9bbebd;padding-left:0" @click="logout">退出登录</el-button></div></aside>
    <main class="main"><header class="topline"><div><div class="eyebrow">{{user.class_id}} 班教学空间</div><h1 style="margin-bottom:0">{{title}}</h1></div><el-button :loading="busy" @click="action(load)">刷新</el-button></header><div v-if="error" class="error" role="alert">{{error}}</div>

    <template v-if="page==='overview'"><div class="stats"><div class="stat"><span class="muted">学习助手</span><b>{{lists.agents.length}}</b></div><div class="stat"><span class="muted">讲义材料</span><b>{{lists.materials.length}}</b></div><div class="stat"><span class="muted">{{teacher?'待确认知识缺口':'我的错题'}}</span><b>{{teacher?lists.gaps.filter(g=>g.state==='pending').length:lists.wrong.length}}</b></div></div><section class="card"><h2>{{teacher?'从一份讲义开始':'今天想学些什么'}}</h2><p class="muted">{{teacher?'上传讲义，绑定学习助手；学生未能获得答案的问题会汇总到知识缺口，审核后可以补充材料。':'选择学习助手查阅本班讲义，或打开自己的作业。回答引用的讲义可以查看原始片段。'}}</p><div class="row"><el-button type="primary" @click="page='chat'">进入学习助手</el-button><el-button @click="page=teacher?'materials':'assignments'">{{teacher?'管理讲义':'查看作业'}}</el-button></div></section><div class="grid"><section class="card"><h2>本班应用</h2><div v-for="agent in lists.agents" :key="agent.id" class="list-item"><b>{{agent.name}}</b><p class="muted">已绑定 {{agent.material_ids.length}} 份材料 · {{agent.skill_ids.length}} 项技能</p></div></section><section class="card"><h2>最近的作业</h2><div v-for="a in lists.assignments.slice(0,5)" :key="a.id" class="list-item"><b>{{a.title}}</b><p class="muted">截止 {{date(a.deadline)}} · {{state(a.state)}}</p></div><div v-if="!lists.assignments.length" class="empty">暂时没有作业</div></section></div></template>

    <template v-if="page==='chat'"><div class="chat-layout"><section class="card"><label>学习助手</label><el-select v-model="agentId" :disabled="sending"><el-option v-for="a in lists.agents" :key="a.id" :label="a.name" :value="a.id"/></el-select><el-button type="primary" style="width:100%;margin:12px 0 25px" @click="createConversation">新建会话</el-button><button v-for="c in lists.conversations" :key="c.id" class="conversation-button" :class="{active:conversationId===c.id}" :disabled="sending" @click="openConversation(c)">{{c.title}}</button></section><section class="card"><div class="row spread"><h2>{{lists.agents.find(a=>a.id===agentId)?.name||'选择一个学习助手'}}</h2><span class="badge">本班材料范围</span></div><div class="messages"><div v-if="!chatRows.length" class="empty">可以询问讲义内容、查看当前作业或回顾自己的错题。</div><div v-for="(m,i) in chatRows" :key="i" class="message" :class="m.role"><strong>{{m.role==='user'?'你':'学习助手'}}{{m.skill?' · '+m.skill:''}}</strong>{{m.content}}<div v-if="m.citations?.length" class="citations"><button v-for="c in m.citations" :key="c.id" class="citation" @click="snapshot=c">[{{c.id}}] {{c.title}} · v{{c.version}}</button></div><p v-if="m.gap_id" class="muted">知识缺口编号 {{m.gap_id}}</p></div></div><details v-if="toolEvents.length"><summary class="muted">查看本轮工具执行（{{toolEvents.length}}）</summary><pre class="pre">{{JSON.stringify(toolEvents,null,2)}}</pre></details><form class="chat-form" @submit.prevent="ask"><el-input v-model="question" type="textarea" :rows="3" maxlength="4000" placeholder="输入问题，回答将逐段显示…" :disabled="sending"/><div class="row spread" style="margin-top:12px"><span class="muted">资料不足时会提示并登记，不编造出处</span><el-button type="primary" native-type="submit" :loading="sending">发送</el-button></div></form></section></div></template>

    <template v-if="page==='materials'"><section v-if="teacher" class="card"><h2>{{replaceId?'更新讲义版本':'上传讲义'}}</h2><div class="fields"><div><label>材料标题</label><el-input v-model="materialTitle" placeholder="如：第一章 分数运算"/></div><div><label>更新对象（留空为新增）</label><el-select v-model="replaceId" clearable placeholder="新增材料"><el-option v-for="m in lists.materials" :key="m.id" :value="m.id" :label="m.title"/></el-select></div><div class="full"><input type="file" accept=".txt,.md,.pdf" aria-label="选择讲义文件" @change="fileChange($event,'material')"/></div></div><el-button type="primary" style="margin-top:16px" :loading="busy" @click="uploadMaterial">上传并建立索引</el-button><p class="muted" style="margin-top:12px">支持 TXT、Markdown 和文字型 PDF。更新期间沿用已生效版本，索引完成后再切换。</p></section><section class="card"><div v-if="!lists.materials.length" class="empty">暂无可用讲义</div><div v-for="m in lists.materials" :key="m.id" class="list-item"><div class="row spread"><h3>{{m.title}}</h3><div class="row"><el-button v-if="m.active_version_id" type="primary" plain @click="previewMaterial(m)">{{materialPreview?.id===m.id?'收起正文':'查看正文'}}</el-button><el-button v-if="m.active_version_id" @click="action(()=>download(m.id))">下载正文</el-button><el-button v-if="teacher&&m.active_version_id" text type="danger" @click="withdraw(m)">撤回</el-button></div></div><div v-for="v in m.versions" :key="v.id" class="muted">v{{v.number}} · <span class="badge">{{state(v.state)}}</span> · {{date(v.created_at)}}<span v-if="v.error"> · {{v.error}}</span></div><div v-if="materialPreview?.id===m.id" class="material-preview"><p class="muted">当前生效版本的可检索正文；PDF 原始排版不在此处保留。</p><pre class="pre">{{materialPreview?.content}}</pre></div></div></section></template>

    <template v-if="page==='config'&&teacher"><div class="grid"><section class="card"><h2>提示词模板</h2><label>名称</label><el-input v-model="templateForm.name"/><label>模板正文</label><el-input v-model="templateForm.content" type="textarea" :rows="5"/><el-button type="primary" style="margin-top:12px" @click="saveTemplate">保存模板</el-button><div v-for="t in lists.templates" :key="t.id" class="list-item"><div class="row spread"><b>{{t.name}}</b><el-button text @click="Object.assign(templateForm,t)">编辑</el-button></div><p class="muted">{{t.content}}</p></div></section><section class="card"><h2>技能文件</h2><p class="muted">标准 SKILL.md：YAML 中填写 name 和 description，随后用 Markdown 描述技能行为。</p><input type="file" accept=".md,.txt" aria-label="选择技能文件" @change="fileChange($event,'skill')"/><el-button type="primary" style="margin-top:12px" @click="uploadSkill">上传技能</el-button><div v-for="s in lists.skills" :key="s.id" class="list-item"><div class="row spread"><b>{{s.name}}</b><el-switch :model-value="s.enabled" :aria-label="s.name+'启用'" @change="action(async()=>{await api('/skills/'+s.id,'PATCH',{enabled:!s.enabled});await load()})"/></div><p class="muted">{{s.description}}</p><details><summary class="muted">技能正文</summary><pre class="pre">{{s.body}}</pre></details></div></section></div><section id="agent-form" class="card"><h2>{{agentForm.id?'编辑应用':'创建应用'}}</h2><div class="fields"><div><label>应用名称</label><el-input v-model="agentForm.name"/></div><div><label>提示词模板</label><el-select v-model="agentForm.template_id" clearable><el-option v-for="t in lists.templates" :key="t.id" :value="t.id" :label="t.name"/></el-select></div><div class="full"><label>应用角色（未绑定模板时使用）</label><el-input v-model="agentForm.prompt" type="textarea" :rows="2"/></div><div><label>讲义范围</label><el-select v-model="agentForm.material_ids" multiple><el-option v-for="m in lists.materials" :key="m.id" :value="m.id" :label="m.title"/></el-select></div><div><label>可用技能</label><el-select v-model="agentForm.skill_ids" multiple><el-option v-for="s in lists.skills" :key="s.id" :value="s.id" :label="s.name"/></el-select></div><div class="full"><label>外部工具</label><el-checkbox-group v-model="agentForm.tools"><el-checkbox v-for="t in toolOptions" :key="t[0]" :value="t[0]">{{t[1]}}</el-checkbox></el-checkbox-group></div></div><div class="row" style="margin-top:20px"><el-button type="primary" @click="saveAgent">保存应用</el-button><el-button @click="Object.assign(agentForm,{id:0,name:'',template_id:null,material_ids:[],skill_ids:[],tools:[],enabled:true})">新建</el-button></div></section><section class="card"><div v-for="a in lists.agents" :key="a.id" class="list-item row spread"><div><b>{{a.name}}</b><p class="muted">{{a.material_ids.length}} 份讲义 · {{a.skill_ids.length}} 个技能 · {{a.tools.length}} 项工具</p></div><div><el-button @click="editAgent(a)">编辑</el-button><el-button text @click="action(async()=>{await api('/agents/'+a.id,'PATCH',{enabled:!a.enabled});await load()})">{{a.enabled?'停用':'启用'}}</el-button></div></div></section></template>

    <template v-if="page==='gaps'&&teacher"><div class="tagline">学生提问未获得足够材料依据时，系统会登记候选缺口。同班相近问题合并计数，补充材料完成索引并命中原问题后才标记“已补入”。</div><section v-for="gap in lists.gaps" :key="gap.id" class="card"><div class="row spread"><span class="badge">{{state(gap.state)}}</span><span class="muted">提问热度 {{gap.heat}}</span></div><p class="gap-summary">{{gap.question}}</p><div class="row inline-actions"><el-button v-if="['pending','index_failed'].includes(gap.state)" type="primary" @click="reviewGap(gap,'approve')">确认缺口</el-button><el-button v-if="['pending','approved','index_failed'].includes(gap.state)" @click="reviewGap(gap,'reject')">驳回</el-button><el-button v-if="['approved','index_failed'].includes(gap.state)" @click="Object.assign(supplementForm,{id:gap.id,title:'补充讲义',content:''})">补充材料</el-button></div><p v-if="gap.note" class="muted">{{gap.note}}</p><details v-if="gap.state==='filled'"><summary class="muted">查看回补前后检索结果</summary><pre class="pre">{{JSON.stringify({before:gap.before_hits,after:gap.after_hits},null,2)}}</pre></details></section><div v-if="!lists.gaps.length" class="card empty">暂时没有候选缺口</div></template>

    <template v-if="page==='assignments'"><section v-if="teacher" class="card"><h2>创建同纲作业</h2><div class="fields"><div><label>作业名称</label><el-input v-model="assignmentForm.title"/></div><div><label>截止时间</label><el-input v-model="assignmentForm.deadline" type="datetime-local"/></div><div class="full"><label>题干模板（用 {a}、{b} 表示变量）</label><el-input v-model="assignmentForm.question_template" type="textarea" :rows="2"/></div><div><label>参数范围 JSON</label><el-input v-model="assignmentForm.ranges"/></div><div><label>服务端答案表达式</label><el-input v-model="assignmentForm.answer_expression"/></div><div class="full"><label>Rubric JSON（满分总计100）</label><el-input v-model="assignmentForm.rubric" type="textarea" :rows="2"/></div></div><el-button type="primary" style="margin-top:18px" @click="newAssignment">保存草稿</el-button></section><section class="card"><h2>作业列表</h2><div v-for="a in lists.assignments" :key="a.id" class="list-item row spread"><div><b>{{a.title}}</b><p class="muted">{{state(a.state)}} · 截止 {{date(a.deadline)}}</p></div><el-button v-if="teacher" type="primary" @click="publishAssignment(a.id)">{{a.state==='draft'?'发布并发卷':'检查未发卷学生'}}</el-button></div><div v-if="!lists.assignments.length" class="empty">暂无作业</div></section><section class="card"><h2>{{teacher?'学生试卷':'我的试卷'}}</h2><div v-for="p in lists.papers" :key="p.id" class="list-item"><div class="row spread"><b>{{assignmentName(p.assignment_id)}}<span v-if="teacher"> · {{studentName(p.user_id)}}</span></b><span class="badge">{{state(p.state)}}</span></div><p class="gap-summary">{{p.question||'等待发卷完成'}}</p><el-button v-if="!teacher&&['ready','frozen'].includes(p.state)" @click="startPaper(p)">{{p.state==='ready'?'开始作答':'继续作答'}}</el-button><p v-if="p.error" class="muted">{{p.error}}</p></div></section><section class="card"><h2>{{teacher?'批改与教师复核':'我的批改结果'}}</h2><div v-for="s in lists.submissions" :key="s.id" class="list-item"><div class="row spread"><b>提交 #{{s.id}}<span v-if="teacher"> · {{studentName(s.user_id)}}</span></b><span class="badge">{{state(s.state)}}</span></div><p v-if="s.final_score!==null"><template v-if="s.state==='reviewed'">教师复核后成绩 <b>{{s.final_score}}</b> / 100 <span class="muted">（AI 初评 {{s.ai_score}} / 100）</span></template><template v-else>AI 批改成绩 <b>{{s.final_score}}</b> / 100</template></p><p class="gap-summary">{{s.feedback}}</p><p v-if="s.review_note" class="muted">教师复核依据：{{s.review_note}}</p><el-button v-if="teacher&&['graded','reviewed'].includes(s.state)" @click="reviewScore(s)">人工复核 / 改分</el-button><details><summary class="muted">查看提交及评分明细</summary><pre class="pre">{{JSON.stringify({answer:s.answer,grading:s.ai_raw},null,2)}}</pre></details></div><div v-if="!lists.submissions.length" class="empty">暂时没有提交记录</div></section><section v-if="!teacher" class="card"><h2>错题记录</h2><div v-for="w in lists.wrong" :key="w.id" class="list-item"><b>提交 #{{w.submission_id}}</b><p class="gap-summary">{{w.explanation}}</p><el-button text @click="page='chat'">去学习助手回顾错因</el-button></div></section></template>

    <template v-if="page==='weekly'"><div class="row spread" style="margin-bottom:20px"><p class="muted">指标由程序统计，AI提供解读，教师确认后发布。</p><el-button v-if="teacher" type="primary" @click="newWeekly">生成本周报告</el-button></div><section v-for="report in lists.weekly" :key="report.id" class="card"><div class="row spread"><h2>{{date(report.period_start).split(' ')[0]}} 起一周</h2><span class="badge">{{state(report.state)}}</span></div><template v-if="Object.keys(report.facts).length"><div class="stats"><div class="stat"><span class="muted">检索次数</span><b>{{report.facts.search_count}}</b></div><div class="stat"><span class="muted">作业提交</span><b>{{report.facts.submission_count}}</b></div><div class="stat"><span class="muted">平均成绩</span><b>{{report.facts.average_score??'—'}}</b></div></div><ScoreChart :facts="report.facts"/><p v-if="!report.facts.sample_sufficient" class="tagline">本周记录不够，暂不推断学习趋势。</p><label>教学观察与建议</label><el-input v-if="teacher&&report.state==='draft'" v-model="report.teacher_comment" type="textarea" :rows="5"/><p v-else class="gap-summary" style="white-space:pre-wrap">{{report.teacher_comment}}</p><el-button v-if="teacher&&report.state==='draft'" type="primary" style="margin-top:14px" @click="publishWeekly(report)">确认并发布</el-button><details style="margin-top:18px"><summary class="muted">查看统计依据</summary><pre class="pre">{{JSON.stringify(report.facts,null,2)}}</pre></details></template></section><div v-if="!lists.weekly.length" class="card empty">{{teacher?'尚未生成本周报告':'暂无已发布周报'}}</div></template>

    <template v-if="page==='tasks'&&teacher"><section class="card"><h2>任务状态</h2><p class="muted">索引、发卷、批改和周报在后台执行，失败记录会保留。可以在排查原因后重试。</p><el-table :data="lists.tasks"><el-table-column prop="kind" label="任务类型" width="100"/><el-table-column prop="target_id" label="对象" width="80"/><el-table-column label="状态" width="130"><template #default="{row}">{{state(row.state)}}</template></el-table-column><el-table-column prop="attempts" label="执行次数" width="100"/><el-table-column prop="error" label="错误说明"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="['failed','dispatch_failed'].includes(row.state)" text type="primary" @click="retryTask(row)">重试</el-button></template></el-table-column></el-table></section></template>

    <template v-if="page==='audit'&&teacher"><section class="card"><h2>请求与工具记录</h2><p class="muted">按请求编号关联模型参数、工具调用和结果，记录中不包含登录令牌或模型密钥。</p><div v-for="a in lists.audit" :key="a.id" class="list-item"><div class="row spread"><b>{{a.action}}</b><span class="muted">{{date(a.created_at)}} · {{a.success?'成功':'失败'}}</span></div><details><summary class="muted">{{a.request_id}}</summary><pre class="pre">{{JSON.stringify(a.details,null,2)}}</pre></details></div></section></template>
    <p class="footer-note">CampusClaw Nexus · {{user.class_id}} 班 · {{teacher?'教师工作空间':'学生学习空间'}}</p>
    </main>
    <el-dialog :model-value="!!snapshot" :title="snapshot?.title+' · 引用快照'" width="650px" @close="snapshot=null"><p class="muted">版本 {{snapshot?.version}} · 原文位置 {{snapshot?.start}}–{{snapshot?.end}}</p><pre class="pre">{{snapshot?.content}}</pre><p class="muted">此处保留回答生成时的材料片段，讲义更新后仍可核对。</p></el-dialog>
    <el-dialog :model-value="!!supplementForm.id" title="补充知识材料" width="650px" @close="supplementForm.id=0"><label>讲义标题</label><el-input v-model="supplementForm.title"/><label>补充正文</label><el-input v-model="supplementForm.content" type="textarea" :rows="10"/><el-button type="primary" style="margin-top:18px" @click="supplement">提交并建立索引</el-button></el-dialog>
    <el-dialog :model-value="!!answerForm.id" title="我的作业" width="650px" @close="answerForm.id=0"><p class="gap-summary">{{answerForm.question}}</p><p class="muted">题目实例已冻结。请把最终数值写在回答最后，便于核对。</p><el-input v-model="answerForm.answer" type="textarea" :rows="8" placeholder="填写过程和最终答案"/><el-button type="primary" style="margin-top:18px" @click="submitPaper">提交作业</el-button></el-dialog>
  </div>
</template>
